MAX_BYTES = 1_048_576
MAX_SIDE = 1024


def finish(img):
    """A light photographic finish: warm grade, vignette, grain."""
    img = ImageEnhance.Color(img).enhance(1.05)
    img = ImageEnhance.Brightness(img).enhance(1.01)
    w, h = img.size
    mask = Image.new("L", (w, h), 0)
    draw = ImageDraw.Draw(mask)
    draw.ellipse((-w * 0.25, -h * 0.25, w * 1.25, h * 1.25), fill=255)
    mask = mask.filter(ImageFilter.GaussianBlur(120))
    dark = ImageEnhance.Brightness(img).enhance(0.82)
    img = Image.composite(img, dark, mask)
    random.seed(20261121)
    noise = Image.effect_noise((w, h), 6).convert("L")
    grey = Image.merge("RGB", (noise, noise, noise))
    img = Image.blend(img, grey, 0.03)
    return img


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else "/output/entry.png"
    img = Image.open(io.BytesIO(base64.b64decode(PHOTO_JPEG_B64))).convert("RGB")
    img.thumbnail((MAX_SIDE, MAX_SIDE), Image.LANCZOS)
    img = finish(img)
    while True:
        buf = io.BytesIO()
        img.save(buf, "PNG", optimize=True)
        if buf.tell() <= MAX_BYTES or min(img.size) <= 320:
            break
        img = img.resize(
            (int(img.width * 0.9), int(img.height * 0.9)), Image.LANCZOS
        )
    data = buf.getvalue()
    folder = os.path.dirname(out)
    if folder:
        os.makedirs(folder, exist_ok=True)
    with open(out, "wb") as handle:
        handle.write(data)
    print("wrote", out, img.size, len(data), "bytes")


if __name__ == "__main__":
    main()
